#!/usr/bin/env python3
"""Brute-force reference returning EXACT rationals (for differential testing)."""
import json, math
from itertools import product

C2P, P2P, P2C = 0, 1, 2
G = {(0,0):0,(0,1):0,(0,2):1,(1,0):1,(1,1):1,(1,2):2,(2,0):1,(2,1):1,(2,2):2}

def canon(u,v): return (u,v) if u<v else (v,u)

def normalize(raw, ixps):
    out=[]
    for a in raw:
        if a in ixps: continue
        if out and out[-1]==a: continue
        out.append(a)
    return tuple(out), (len(set(out))!=len(out))

def peel(paths):
    rounds={}; cur=dict(paths); r=0
    while cur:
        r+=1
        info={}
        for p in cur:
            for i in range(len(p)-1):
                info.setdefault(canon(p[i],p[i+1]),[]).append(p)
        marked=[]
        for k,ps in info.items():
            u,v=k
            if all(p[0]==u or p[-1]==u for p in ps) or all(p[0]==v or p[-1]==v for p in ps):
                marked.append(k)
        if not marked: break
        ms=set(marked)
        for k in ms: rounds[k]=r
        nxt={}
        for p,c in cur.items():
            q=p
            if canon(p[0],p[1]) in ms: q=q[1:]
            if canon(p[-2],p[-1]) in ms: q=q[:-1] if len(q)>1 else q[:0]
            if len(q)<2: continue
            nxt[q]=nxt.get(q,0)+c
        cur=nxt
    return rounds,cur

def occurrences(finals, core):
    idx={k:i for i,k in enumerate(core)}
    occ=[]
    for p,c in finals.items():
        n=len(p)
        for i in range(n-1):
            a,b=p[i],p[i+1]
            k=canon(a,b)
            e=idx[k]
            if a<b: q,j=p,i
            else: q,j=p[::-1], n-2-i
            u,v=q[j],q[j+1]
            L=(idx[canon(q[j-1],u)], q[j-1]<u) if j>0 else None
            R=(idx[canon(v,q[j+2])], v<q[j+2]) if j+2<n else None
            occ.append((e,L,R,c))
    return occ

def scopes_of(core, occ):
    sc=[set([i]) for i in range(len(core))]
    for e,L,R,c in occ:
        if L is not None: sc[e].add(L[0])
        if R is not None: sc[e].add(R[0])
    return [tuple(sorted(s)) for s in sc]

def adj_of(scopes):
    n=len(scopes); adj=[set() for _ in range(n)]
    for s in scopes:
        for i in range(len(s)):
            for j in range(i+1,len(s)):
                adj[s[i]].add(s[j]); adj[s[j]].add(s[i])
    return adj

def width_of(order, scopes):
    adj=[set(x) for x in adj_of(scopes)]; n=len(scopes); w=0
    alive=set(range(n))
    for v in order:
        nb = adj[v] & alive
        w=max(w,len(nb))
        for x in nb:
            for y in nb:
                if x!=y: adj[x].add(y)
        alive.discard(v)
    return w

def phi(e, occ, X):
    tot=0
    for (eo,L,R,c) in occ:
        if eo!=e: continue
        lv = C2P if L is None else (X[L[0]] if L[1] else 2-X[L[0]])
        rv = P2C if R is None else (X[R[0]] if R[1] else 2-X[R[0]])
        if X[e]==G[(lv,rv)]: tot+=c
    return tot

def reference(doc):
    """Returns dict or ('zero',) or ('invalid', reason)."""
    ixps=set(doc['ixps'])
    agg={}
    for rec in doc['rib']:
        p,looped=normalize(rec['path'], ixps)
        if looped or len(p)<2: continue
        agg[p]=agg.get(p,0)+rec['count']
    all_links=set()
    for p in agg:
        for i in range(len(p)-1): all_links.add(canon(p[i],p[i+1]))
    rounds, finals = peel(agg)
    core=sorted(all_links-set(rounds))
    idx={k:i for i,k in enumerate(core)}
    m=len(core)
    occ=occurrences(finals, core) if m else []
    scopes=scopes_of(core, occ)
    sums=[[0,0,0] for _ in range(m)]
    Z=0
    for states in product(range(3), repeat=m):
        X=list(states)
        w=1
        for e in range(m):
            w*=phi(e,occ,X)
        if w==0: continue
        Z+=w
        for e in range(m): sums[e][X[e]]+=w
    if m and Z==0: return {'error':'zero-partition'}
    prob={}
    for i,k in enumerate(core): prob[k]=(sums[i][0],sums[i][1],sums[i][2],Z)
    priors={}
    rel={'c2p':0,'p2p':1,'p2c':2}
    for rec in doc['priors']:
        u,v=rec['link']; w=rec['weights']; s=sum(w)
        vec=((w[0],s),(w[1],s),(w[2],s))
        priors[canon(u,v)] = vec if u<v else (vec[2],vec[1],vec[0])
    declared={}
    for rec in doc['declared']:
        u,v=rec['link']
        vec=[(0,1),(0,1),(0,1)]; vec[rel[rec['rel']]]=(1,1); vec=tuple(vec)
        declared[canon(u,v)] = vec if u<v else (vec[2],vec[1],vec[0])
    links=[]
    for k in sorted(all_links):
        r=rounds.get(k,0)
        if r==0:
            a,b,c,Z_=prob[k]; pr=(a,b,c,Z_)
        else:
            vec=priors.get(k)
            pr = None if vec is None else (vec[0][0],vec[1][0],vec[2][0],vec[0][1])
        links.append({'link':list(k),'round':r,'prob':pr})
    queries=[]
    for rec in doc['queries']:
        p,looped=normalize(rec['path'], ixps)
        out={'id':rec['id'],'path':list(p),'status':'ok','score':None,'full':None,'witness':None,'leaked':None}
        if looped:
            out['status']='loop'; queries.append(out); continue
        n=len(p)
        if n<3:
            out['score']=(1,1); out['full']=1.0; out['leaked']=False
            queries.append(out); continue
        vecs=[]
        for i in range(n-1):
            k,fwd=canon(p[i],p[i+1]), p[i]<p[i+1]
            v=declared.get(k)
            if v is None:
                if k in prob:
                    a,b,c,Z_=prob[k]; v=((a,Z_),(b,Z_),(c,Z_))
                else:
                    v=priors.get(k)
                    if v is None: v=((1,3),(1,3),(1,3))
            if not fwd: v=(v[2],v[1],v[0])
            vecs.append(v)
        legs=[]
        for i in range(n-2):
            nu,du=vecs[i][0]; nd,dd=vecs[i+1][2]
            num=nu*dd+nd*du-nu*nd; den=du*dd
            g=math.gcd(num,den)
            legs.append((num//g,den//g))
        bi=0
        for i in range(1,len(legs)):
            if legs[i][0]*legs[bi][1] < legs[bi][0]*legs[i][1]: bi=i
        a,b=rec['threshold']; num,den=legs[bi]
        sc,sd,sp=1.0,0.0,0.0
        for v in vecs:
            pc=v[0][0]/v[0][1]; pp=v[1][0]/v[1][1]; pd=v[2][0]/v[2][1]
            sc,sd,sp=sc*pc,(sc+sd)*pd, sc*pp+sp*pd
        out['score']=(num,den); out['full']=sc+sd+sp; out['witness']=bi
        out['leaked']= num*b < a*den
        queries.append(out)
    return {'version':1,'links':links,'queries':queries,'scopes':scopes,'core':core,'rounds':{str(k):v for k,v in rounds.items()}}

def floats(res):
    out={'version':1,'links':[],'queries':[]}
    for rec in res['links']:
        pr=rec['prob']
        pr=[1/3,1/3,1/3] if pr is None else [pr[0]/pr[3],pr[1]/pr[3],pr[2]/pr[3]]
        out['links'].append({'link':rec['link'],'round':rec['round'],'prob':pr})
    for q in res['queries']:
        s=q['score']
        out['queries'].append({'id':q['id'],'path':q['path'],'status':q['status'],
            'score': None if s is None else s[0]/s[1], 'full': q['full'],
            'witness': q['witness'], 'leaked': q['leaked']})
    return out

if __name__=='__main__':
    doc=json.load(math.__dict__['__import__']('sys').stdin) if False else json.load(__import__('sys').stdin)
    res=reference(doc)
    if 'error' in res: print(json.dumps(res))
    else: print(json.dumps(floats(res)))
